	@Test
	void runsIndependentTasksConcurrentlyWithinWorkerLimit() throws Exception {
		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(2, 128, 4)) {
			CountDownLatch started = new CountDownLatch(2);
			CountDownLatch release = new CountDownLatch(1);
			AtomicInteger active = new AtomicInteger();
			AtomicInteger maximumActive = new AtomicInteger();
			Callable<Void> operation = () -> {
				int current = active.incrementAndGet();
				maximumActive.accumulateAndGet(current, Math::max);
				started.countDown();
				try {
					if (!release.await(10, TimeUnit.SECONDS)) {
						throw new AssertionError("concurrency test was not released");
					}
					return null;
				} finally {
					active.decrementAndGet();
				}
			};
			Future<Void> first = scheduler.submit(reserve(scheduler, 48, 2), operation);
			Future<Void> second = scheduler.submit(reserve(scheduler, 48, 2), operation);
			try {
				assertThat(started.await(10, TimeUnit.SECONDS)).isTrue();
				assertThat(maximumActive.get()).isEqualTo(2);
			} finally {
				release.countDown();
			}
			first.get(10, TimeUnit.SECONDS);
			second.get(10, TimeUnit.SECONDS);
			assertThat(scheduler.peakActiveTasks()).isLessThanOrEqualTo(2);
			assertThat(scheduler.peakReservedMemoryBytes()).isLessThanOrEqualTo(128);
			assertThat(scheduler.peakReservedFileDescriptors()).isLessThanOrEqualTo(4);
		}
	}

