	@Test
	void scanEnvelopeAdmitsReaderConversionAndNestedSpillAsOneMinimumOperation() throws Exception {
		long producerBytes = 32L * 1024L;
		long readerBytes = BulkLz4.mergeInputMemoryBytes(BulkCodec.NONE);
		long spillBytes = BulkLz4.mergeOutputMemoryBytes(BulkCodec.NONE);
		long conversionBytes = 4096L;
		long scanBytes = Math.addExact(Math.addExact(readerBytes, conversionBytes), spillBytes);
		long configuredBudget = producerBytes + scanBytes - 1L;
		Path directory = Files.createTempDirectory("bulk-scan-envelope");
		Path inputPath = directory.resolve("input.bin");
		Path outputPath = directory.resolve("output.bin");
		Files.write(inputPath, new byte[] { 42 });
		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(1, configuredBudget, 2);
				BulkTaskScheduler.ResourceLease producer = reserve(scheduler, producerBytes, 0);
				BulkTaskScheduler.ResourceScope scan = scheduler.reserveScanEnvelope(readerBytes, 1,
						conversionBytes, spillBytes, 1);
				DataInputStream input = BulkLz4.input(inputPath, BulkCodec.NONE, scheduler);
				DataOutputStream output = BulkLz4.output(outputPath, BulkCodec.NONE, scheduler)) {
			assertThat(scan.isExclusiveMemoryFloor()).isTrue();
			assertThat(input.readByte()).isEqualTo((byte) 42);
			output.writeByte(7);
			assertThat(scheduler.openFileHandles())
					.as("the reserved input and nested spill can be live together")
					.isEqualTo(2);
			assertThat(scheduler.peakReservedMemoryBytes()).isEqualTo(producerBytes + scanBytes);
			assertThat(scheduler.effectiveMemoryMinimumBytes()).isEqualTo(producerBytes + scanBytes);
		} finally {
			Files.deleteIfExists(outputPath);
			Files.deleteIfExists(inputPath);
			Files.deleteIfExists(directory);
		}
	}

