	@Test
	void adaptiveCoordinatorConsumesCompletionOrderAndPreservesSourceConcurrencyMetadata() throws Exception {
		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(2, 64, 4)) {
			AtomicInteger nextWork = new AtomicInteger();
			AtomicInteger preparedWorkCleanup = new AtomicInteger();
			CountDownLatch slowStarted = new CountDownLatch(1);
			CountDownLatch releaseSlow = new CountDownLatch(1);
			CountDownLatch fastConsumed = new CountDownLatch(1);
			List<BulkTaskScheduler.AdaptiveCompletion<Integer>> completions = Collections.synchronizedList(
					new ArrayList<>());
			AtomicReference<Throwable> runnerFailure = new AtomicReference<>();
			BulkTaskScheduler.AdaptiveWorkSource<Integer> source = () -> {
				int work = nextWork.getAndIncrement();
				if (work == 0) {
					return request(new BulkTaskScheduler.AdaptiveWorkRequest<>(32L, 1, false, 7L, 3, lease -> {
						assertThat(lease.memoryBytes()).isEqualTo(32L);
						assertThat(lease.fileDescriptors()).isEqualTo(1);
						assertThat(scheduler.isWorkerThread()).isFalse();
						return new BulkTaskScheduler.AdaptivePreparedWork<>(100L, taskLease -> {
							slowStarted.countDown();
							awaitCleanup(releaseSlow, "slow adaptive operation was not released");
							return new BulkTaskScheduler.AdaptiveTaskResult<>(0, 11L);
						}, preparedWorkCleanup::incrementAndGet);
					}));
				}
				if (work == 1) {
					return request(new BulkTaskScheduler.AdaptiveWorkRequest<>(32L, 1, false, 7L, 3, lease -> {
						assertThat(lease.memoryBytes()).isEqualTo(32L);
						assertThat(lease.fileDescriptors()).isEqualTo(1);
						assertThat(scheduler.isWorkerThread()).isFalse();
						return new BulkTaskScheduler.AdaptivePreparedWork<>(101L, taskLease -> {
							assertThat(slowStarted.await(10, TimeUnit.SECONDS)).isTrue();
							return new BulkTaskScheduler.AdaptiveTaskResult<>(1, 17L);
						}, preparedWorkCleanup::incrementAndGet);
					}));
				}
				return exhausted();
			};
			Thread coordinator = new Thread(() -> {
				try {
					scheduler.runAdaptive(source, completion -> {
						completions.add(completion);
						if (completion.workId() == 101L) {
							fastConsumed.countDown();
						}
					});
				} catch (Throwable failure) {
					runnerFailure.set(failure);
				}
			});
			coordinator.start();
			try {
				assertThat(fastConsumed.await(10, TimeUnit.SECONDS)).isTrue();
				assertThat(completions).hasSize(1);
				assertThat(completions.get(0).workId()).isEqualTo(101L);
				assertThat(completions.get(0).actualActivePartitions()).isEqualTo(3);
				assertThat(completions.get(0).stageEpoch()).isEqualTo(7L);
				assertThat(completions.get(0).committedWorkBytes()).isEqualTo(17L);
			} finally {
				releaseSlow.countDown();
				coordinator.join(TimeUnit.SECONDS.toMillis(10));
			}
			assertThat(coordinator.isAlive()).isFalse();
			assertThat(runnerFailure.get()).isNull();
			assertThat(completions).extracting(BulkTaskScheduler.AdaptiveCompletion::workId)
					.containsExactly(101L, 100L);
			assertThat(preparedWorkCleanup).hasValue(2);
			assertThat(scheduler.reservedMemoryBytes()).isZero();
			assertThat(scheduler.reservedFileDescriptors()).isZero();
		}
	}

	@Test
	void adaptiveSourceWaitsForPendingPartitionLeavesBeforeAdvancing() throws Exception {
		int partitionCount = 12;
		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(1, 32, 2)) {
			AtomicInteger nextPartition = new AtomicInteger();
			AtomicInteger pendingLeaves = new AtomicInteger();
			AtomicInteger active = new AtomicInteger();
			AtomicInteger maximumActive = new AtomicInteger();
			List<Long> completedPartitions = new ArrayList<>();

			scheduler.runAdaptive(() -> {
				if (pendingLeaves.get() != 0) {
					// This partition's cursor is at EOF, but its submitted leaf has not been consumed yet.
					return waitForWork();
				}
				int partition = nextPartition.getAndIncrement();
				if (partition == partitionCount) {
					return exhausted();
				}
				pendingLeaves.incrementAndGet();
				return request(new BulkTaskScheduler.AdaptiveWorkRequest<>(16L, 1, false, partition, 1,
						lease -> new BulkTaskScheduler.AdaptivePreparedWork<>((long) partition, taskLease -> {
							int current = active.incrementAndGet();
							maximumActive.accumulateAndGet(current, Math::max);
							try {
								return new BulkTaskScheduler.AdaptiveTaskResult<>((long) partition, 1L);
							} finally {
								active.decrementAndGet();
							}
						}, () -> {
						})));
			}, completion -> {
				completedPartitions.add(completion.workId());
				pendingLeaves.decrementAndGet();
			});

			assertThat(completedPartitions).containsExactly(
					0L, 1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L, 10L, 11L);
			assertThat(maximumActive).hasValue(1);
			assertThat(nextPartition).hasValue(partitionCount + 1);
		}
	}

