	@Test
	void adaptiveWaitWithoutOutstandingWorkBlocksOnSourceReadiness() throws Exception {
		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(1, 16, 1)) {
			AtomicInteger polls = new AtomicInteger();
			AtomicInteger consumed = new AtomicInteger();
			CountDownLatch awaitingReadiness = new CountDownLatch(1);
			CountDownLatch makeReady = new CountDownLatch(1);
			AtomicReference<Throwable> coordinatorFailure = new AtomicReference<>();
			BulkTaskScheduler.AdaptiveWorkSource<Integer> source = new BulkTaskScheduler.AdaptiveWorkSource<>() {
				@Override
				public BulkTaskScheduler.AdaptiveWorkPoll<Integer> poll() {
					return switch (polls.getAndIncrement()) {
					case 0 -> waitForWork();
					case 1 -> request(new BulkTaskScheduler.AdaptiveWorkRequest<>(16L, 1, false, 1L, 1,
							lease -> new BulkTaskScheduler.AdaptivePreparedWork<>(1L,
									taskLease -> new BulkTaskScheduler.AdaptiveTaskResult<>(1, 1L), () -> {
									})));
					default -> exhausted();
					};
				}

				@Override
				public void awaitReady() throws InterruptedException {
					awaitingReadiness.countDown();
					makeReady.await();
				}
			};
			Thread coordinator = new Thread(() -> {
				try {
					scheduler.runAdaptive(source, completion -> consumed.incrementAndGet());
				} catch (Throwable failure) {
					coordinatorFailure.set(failure);
				}
			});
			coordinator.start();
			try {
				assertThat(awaitingReadiness.await(10, TimeUnit.SECONDS)).isTrue();
				assertThat(polls).hasValue(1);
				assertThat(coordinator.isAlive()).isTrue();
			} finally {
				makeReady.countDown();
				coordinator.join(TimeUnit.SECONDS.toMillis(10));
			}

			assertThat(coordinator.isAlive()).isFalse();
			assertThat(coordinatorFailure.get()).isNull();
			assertThat(polls).hasValue(3);
			assertThat(consumed).hasValue(1);
		}
	}

