	@Test
	void adaptiveRetainedCompletionBackpressuresPreparationAndSerialFloor() throws Exception {
		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(1, 16, 2)) {
			BulkTaskScheduler.ResourceLease cursorLease = reserve(scheduler, 4, 1);
			BulkTaskScheduler.FileDescriptorScope cursorScope = scheduler.bindResourceLease(cursorLease);
			BulkTaskScheduler.OpenFileHandle cursorHandle = scheduler.trackOpenFileHandle();
			AtomicInteger nextRequest = new AtomicInteger();
			AtomicBoolean floorPrepared = new AtomicBoolean();
			AtomicInteger firstResultCleanup = new AtomicInteger();
			AtomicInteger floorResultCleanup = new AtomicInteger();
			CountDownLatch firstConsumerStarted = new CountDownLatch(1);
			CountDownLatch releaseFirstConsumer = new CountDownLatch(1);
			CountDownLatch floorConsumerStarted = new CountDownLatch(1);
			CountDownLatch releaseFloorConsumer = new CountDownLatch(1);
			AtomicReference<Throwable> observerFailure = new AtomicReference<>();
			Thread observer = new Thread(() -> {
				try {
					assertThat(firstConsumerStarted.await(10, TimeUnit.SECONDS)).isTrue();
					assertThat(floorPrepared).as("floor preparation waits for retained completion").isFalse();
					releaseFirstConsumer.countDown();
					assertThat(floorConsumerStarted.await(10, TimeUnit.SECONDS)).isTrue();
					BulkTaskScheduler.ResourceLease blocked = scheduler.tryReserve(0L, 0);
					assertThat(blocked).as("exclusive floor gate remains until result consumption").isNull();
				} catch (Throwable failure) {
					observerFailure.set(failure);
				} finally {
					releaseFirstConsumer.countDown();
					releaseFloorConsumer.countDown();
				}
			});
			observer.start();
			try {
				scheduler.runAdaptive(() -> switch (nextRequest.getAndIncrement()) {
				case 0 -> request(new BulkTaskScheduler.AdaptiveWorkRequest<>(12L, 0, false, 1L, 1,
						lease -> new BulkTaskScheduler.AdaptivePreparedWork<>(10L,
								taskLease -> new BulkTaskScheduler.AdaptiveTaskResult<>("ordinary", 1L,
										firstResultCleanup::incrementAndGet),
								() -> {
								})));
				case 1 -> request(new BulkTaskScheduler.AdaptiveWorkRequest<>(24L, 2, true, 1L, 1,
						lease -> {
							floorPrepared.set(true);
							return new BulkTaskScheduler.AdaptivePreparedWork<>(11L, taskLease -> {
								assertThat(taskLease.memoryBytes()).isEqualTo(24L);
								assertThat(taskLease.fileDescriptors()).isEqualTo(2);
								assertThat(scheduler.reservedMemoryBytes()).isEqualTo(24L);
								assertThat(scheduler.reservedFileDescriptors()).isEqualTo(2);
								try (BulkTaskScheduler.OpenFileHandle ignored = scheduler.trackOpenFileHandle()) {
									return new BulkTaskScheduler.AdaptiveTaskResult<>("floor", 1L,
											floorResultCleanup::incrementAndGet);
								}
							}, () -> {
							});
						}, cursorLease));
				default -> exhausted();
				}, completion -> {
					if (completion.workId() == 10L) {
						firstConsumerStarted.countDown();
						awaitCleanup(releaseFirstConsumer, "ordinary completion consumer was not released");
					} else {
						floorConsumerStarted.countDown();
						awaitCleanup(releaseFloorConsumer, "floor completion consumer was not released");
					}
				});
			} finally {
				releaseFirstConsumer.countDown();
				releaseFloorConsumer.countDown();
				observer.join(TimeUnit.SECONDS.toMillis(10));
				cursorHandle.close();
				cursorScope.close();
				cursorLease.close();
			}

			assertThat(observer.isAlive()).isFalse();
			assertThat(observerFailure.get()).isNull();
			assertThat(floorPrepared).isTrue();
			assertThat(firstResultCleanup).hasValue(1);
			assertThat(floorResultCleanup).hasValue(1);
			assertThat(scheduler.reservedMemoryBytes()).isZero();
			assertThat(scheduler.reservedFileDescriptors()).isZero();
		}
	}

